import { type HTMLAttributes } from "react";
import { Skeleton } from "../ui/Skeleton";
import { CompositionRoot } from "./_CompositionRoot";
import type { CompositionSurfaceProps } from "./composition";

export interface LoadingStateCardProps extends Omit<HTMLAttributes<HTMLDivElement>, "title" | "color">, CompositionSurfaceProps {
  "data-balsa"?: string;
  title?: string;
  description?: string;
  rows?: number;
}

export function LoadingStateCard({
  title = "Loading activity",
  description = "Fetching the latest workspace events.",
  rows = 4,
  headingLevel,
  shadow,
  theme,
  "data-balsa": _dataBalsa,
  ...domProps
}: LoadingStateCardProps) {
  void _dataBalsa;

  return (
    <CompositionRoot
      {...domProps}
      title={title}
      description={description}
      headingLevel={headingLevel}
      shadow={shadow}
      theme={theme}
      data-composition="loading-state"
      aria-busy="true"
      aria-live="polite"
    >
      <span className="sr-only">Loading</span>
      <div className="grid flex-1 content-between gap-balsa-lg">
        {Array.from({ length: rows }, (_, index) => (
          <div key={index} className="grid grid-cols-[2.5rem_minmax(0,1fr)_4rem] items-center gap-balsa-md">
            <Skeleton className="size-10 rounded-balsa-control" />
            <div className="grid gap-balsa-xs">
              <Skeleton className="h-3 w-2/3" />
              <Skeleton className="h-3 w-1/2" />
            </div>
            <Skeleton className="h-3 w-full" />
          </div>
        ))}
      </div>
    </CompositionRoot>
  );
}

import { type HTMLAttributes, type ReactNode } from "react";
import { mergeClasses } from "../ui/classes";
import { ApplicationCard } from "./ApplicationCard";
import type { CompositionSurfaceProps } from "./composition";

export interface CompositionRootProps extends Omit<HTMLAttributes<HTMLDivElement>, "title" | "color">, CompositionSurfaceProps {
  "data-balsa"?: string;
  title: string;
  description?: string;
  action?: ReactNode;
  footer?: ReactNode;
  children?: ReactNode;
}

export function CompositionRoot({
  title,
  description,
  headingLevel = 2,
  shadow = "auto",
  theme,
  action,
  footer,
  children,
  className,
  "data-balsa": _dataBalsa,
  ...domProps
}: CompositionRootProps) {
  void _dataBalsa;

  return (
    <ApplicationCard
      {...domProps}
      title={title}
      description={description}
      headingLevel={headingLevel}
      shadow={shadow ?? "auto"}
      theme={theme}
      action={action}
      footer={footer}
      className={mergeClasses("min-w-0", className)}
    >
      {children}
    </ApplicationCard>
  );
}

import type { Shadow, ThemeInput } from "../ui/theme";

export interface CompositionSurfaceProps {
  headingLevel?: 2 | 3 | 4 | 5 | 6;
  shadow?: Shadow;
  theme?: ThemeInput;
}

export interface CompositionOption {
  label: string;
  value: string;
  description?: string;
}

export interface CompositionMetric {
  label: string;
  value: string;
  detail?: string;
}

export type CompositionPaletteColor = "primary" | "secondary" | "accent";
